388	export async function addReferenceAction(
389	  projectId: string,
390	  formData: FormData
391	): Promise<ActionResult<{ id: string }>> {
392	  const auth = await getAuthenticatedUser()
393	  if (!auth) return { ok: false, error: 'Not authenticated' }
394	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
395	
396	  const supabase = await createClient()
397	
398	  const file = formData.get('file') as File | null
399	  if (!file) return { ok: false, error: 'No file provided' }
400	
401	  // Upload to Supabase Storage
402	  const fileExt = file.name.split('.').pop() ?? 'jpg'
403	  const storagePath = `${auth.studioId}/${projectId}/refs/${Date.now()}.${fileExt}`
404	
405	  const { error: uploadError } = await supabase.storage
406	    .from('project-references')
407	    .upload(storagePath, file, { upsert: false })
408	
409	  if (uploadError) {
410	    logger.error({ uploadError, projectId }, 'addReferenceAction upload failed')
411	    return { ok: false, error: 'Failed to upload image' }
412	  }
413	
414	  const raw = {
415	    storagePath,
416	    caption: (formData.get('caption') as string) || undefined,
417	    displayOrder: formData.get('displayOrder')
418	      ? Number(formData.get('displayOrder'))
419	      : undefined,
420	  }
421	
422	  const parsed = addReferenceSchema.safeParse(raw)
423	  if (!parsed.success) {
424	    return { ok: false, error: 'Validation failed' }
425	  }
426	
427	  try {
428	    const ref = await addProjectReference(auth.studioId, projectId, parsed.data)
429	    revalidatePath(`/projects/${projectId}`)
430	    return { ok: true, data: { id: ref.id } }
431	  } catch (err) {
432	    logger.error({ err, projectId }, 'addReferenceAction failed')
433	    return { ok: false, error: 'Failed to save reference' }
434	  }
435	}
