591	export async function updateProjectStatusAction(
592	  projectId: string,
593	  newStatus: ProjectStatus
594	): Promise<ActionResult<void>> {
595	  const auth = await getAuthenticatedUser()
596	  if (!auth) return { ok: false, error: 'Not authenticated' }
597	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
598	
599	  const supabase = await createClient()
600	
601	  const { data: current, error: fetchErr } = await supabase
602	    .from('projects')
603	    .select('status')
604	    .eq('id', projectId)
605	    .eq('studio_id', auth.studioId)
606	    .single()
607	
608	  if (fetchErr || !current) {
609	    return { ok: false, error: 'Project not found' }
610	  }
611	
612	  const prevStatus = current.status
613	
614	  const { error: updateErr } = await supabase
615	    .from('projects')
616	    .update({ status: newStatus, updated_at: new Date().toISOString() })
617	    .eq('id', projectId)
618	    .eq('studio_id', auth.studioId)
619	
620	  if (updateErr) {
621	    logger.error({ updateErr, projectId }, 'updateProjectStatusAction update failed')
622	    return { ok: false, error: 'Failed to update status' }
623	  }
624	
625	  // Append activity log — best-effort (awaited so ordering is deterministic; never 500 on failure)
626	  try {
627	    const { error: logErr } = await supabase
628	      .from('project_activity_log' as 'projects')
629	      .insert({
630	        project_id: projectId,
631	        actor_id: auth.user.id,
632	        event_type: 'status_changed',
633	        details: { prev_status: prevStatus, new_status: newStatus },
634	      } as never)
635	    if (logErr) logger.warn({ logErr, projectId }, 'activity log insert failed — audit gap')
636	  } catch (err) {
637	    logger.warn({ err, projectId }, 'Failed to insert activity log — audit gap')
638	  }
639	
640	  revalidatePath('/projects')
641	  revalidatePath(`/projects/${projectId}`)
642	  return { ok: true, data: undefined }
643	}
644	
645	// ─── Deposit ledger (new table: project_deposit_transactions) ──────────────────
646	
647	const _depositTransactionSchema = z.object({
648	  amount_cents: z.number().int().positive().max(1_000_000_00, 'Amount exceeds the $1M cap'),
649	  method: z.enum(['stripe', 'cash', 'card', 'other']).optional(),
650	  note: z.string().max(500).optional(),
651	})
652	
653	async function _insertDepositTransaction(
654	  supabase: Awaited<ReturnType<typeof createClient>>,
655	  row: {
656	    project_id: string
657	    type: 'received' | 'applied' | 'refunded' | 'consumed'
658	    amount_cents: number
659	    method?: string | null
660	    note?: string | null
661	    applied_to_session_id?: string | null
662	    created_by: string
663	  }
664	): Promise<{ error: string | null }> {
665	  const { error } = await supabase
666	    .from('project_deposit_transactions' as 'projects')
667	    .insert(row as never)
668	  return { error: error?.message ?? null }
669	}
670	
671	async function _insertActivityLog(
672	  supabase: Awaited<ReturnType<typeof createClient>>,
673	  row: {
674	    project_id: string
675	    actor_id: string
676	    event_type: string
677	    details?: Record<string, unknown>
678	  }
679	): Promise<void> {
680	  const { error } = await supabase
681	    .from('project_activity_log' as 'projects')
682	    .insert(row as never)
683	  if (error) logger.warn({ error, projectId: row.project_id }, 'activity log insert failed')
684	}
685	
686	export async function recordDepositTransactionAction(
687	  projectId: string,
688	  input: { amount_cents: number; method?: string; note?: string }
689	): Promise<ActionResult<void>> {
690	  const auth = await getAuthenticatedUser()
691	  if (!auth) return { ok: false, error: 'Not authenticated' }
692	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can record deposits' }
693	
694	  const parsed = _depositTransactionSchema.safeParse(input)
695	  if (!parsed.success) {
696	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
697	  }
698	
699	  const supabase = await createClient()
700	
701	  // W9 — explicit studio-scope guard before write
702	  const scopeCheck = await verifyProjectInStudio(supabase, auth.studioId, projectId)
703	  if (!scopeCheck.ok) return scopeCheck
704	
705	  const { error } = await _insertDepositTransaction(supabase, {
706	    project_id: projectId,
707	    type: 'received',
708	    amount_cents: parsed.data.amount_cents,
709	    method: parsed.data.method ?? null,
710	    note: parsed.data.note ?? null,
711	    created_by: auth.user.id,
712	  })
713	
714	  if (error) {
715	    logger.error({ error, projectId }, 'recordDepositTransactionAction failed')
716	    return { ok: false, error: 'Failed to record deposit' }
717	  }
718	
719	  await _insertActivityLog(supabase, {
720	    project_id: projectId,
721	    actor_id: auth.user.id,
722	    event_type: 'deposit_received',
723	    details: { amount_cents: parsed.data.amount_cents, method: parsed.data.method ?? null },
724	  })
725	
726	  revalidatePath(`/projects/${projectId}`)
727	  return { ok: true, data: undefined }
728	}
729	
730	export async function applyDepositToSessionAction(
731	  projectId: string,
732	  bookingId: string,
