738	
739	  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }
740	  if (amountCents > 1_000_000_00) return { ok: false, error: 'Amount exceeds the $1M cap' }
741	
742	  const supabase = await createClient()
743	
744	  // W9 — explicit studio-scope guard before write
745	  const scopeCheck = await verifyProjectInStudio(supabase, auth.studioId, projectId)
746	  if (!scopeCheck.ok) return scopeCheck
747	
748	  const { error } = await _insertDepositTransaction(supabase, {
749	    project_id: projectId,
750	    type: 'applied',
751	    amount_cents: amountCents,
752	    applied_to_session_id: bookingId,
753	    created_by: auth.user.id,
