755	
756	  if (error) {
757	    logger.error({ error, projectId, bookingId }, 'applyDepositToSessionAction failed')
758	    return { ok: false, error: 'Failed to apply deposit' }
759	  }
760	
761	  await _insertActivityLog(supabase, {
762	    project_id: projectId,
763	    actor_id: auth.user.id,
764	    event_type: 'deposit_applied',
765	    details: { amount_cents: amountCents, booking_id: bookingId },
766	  })
767	
768	  revalidatePath(`/projects/${projectId}`)
769	  return { ok: true, data: undefined }
770	}
771	
772	export async function consumeDepositAction(
773	  projectId: string,
774	  note?: string
775	): Promise<ActionResult<void>> {
776	  const auth = await getAuthenticatedUser()
777	  if (!auth) return { ok: false, error: 'Not authenticated' }
