788	    .single()
789	
790	  if (!proj || proj.deposit_pool_cents <= 0) {
791	    return { ok: false, error: 'No deposit balance to consume' }
792	  }
793	
794	  const { error } = await _insertDepositTransaction(supabase, {
795	    project_id: projectId,
