'use client'

import { useState, useTransition } from 'react'
import { Check } from 'lucide-react'
import { toast } from 'sonner'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn } from '@/lib/utils'
import { updateProjectStatusAction } from '@/app/(app)/projects/actions'
import type { ProjectStatus } from '@/lib/supabase/types'

// ─── Status config ─────────────────────────────────────────────────────────────

interface StatusConfig {
  label: string
  /** Tailwind class for the colored dot */
  dotClass: string
  /** Tailwind class for the pill container */
  pillClass: string
}

const STATUS_CONFIGS: Record<ProjectStatus, StatusConfig> = {
  planning: {
    label: 'Planning',
    dotClass: 'bg-[var(--color-stone)]',
    pillClass: 'bg-[var(--color-stone)]/10 text-[var(--color-stone)]',
  },
  deposit_paid: {
    label: 'Deposit Paid',
    dotClass: 'bg-amber-500',
    pillClass: 'bg-amber-50 text-amber-700',
  },
  active: {
    label: 'Active',
    dotClass: 'bg-[var(--color-rust)]',
    pillClass: 'bg-[var(--color-rust)]/8 text-[var(--color-rust)] font-italic',
  },
  healing: {
    label: 'Healing',
    dotClass: 'bg-indigo-500',
    pillClass: 'bg-indigo-50 text-indigo-700',
  },
  completed: {
    label: 'Complete',
    dotClass: 'bg-emerald-500',
    pillClass: 'bg-emerald-50 text-emerald-700',
  },
  on_hold: {
    label: 'On Hold',
    dotClass: 'bg-[var(--color-stone)]',
    pillClass: 'bg-[var(--color-stone)]/10 text-[var(--color-stone)]',
  },
  cancelled: {
    label: 'Cancelled',
    dotClass: 'bg-[var(--color-rust)]/60',
    pillClass: 'bg-[var(--color-rust)]/6 text-[var(--color-stone)]',
  },
  archived: {
    label: 'Archived',
    dotClass: 'bg-[var(--color-stone)]/40',
    pillClass: 'bg-[var(--color-stone)]/6 text-[var(--color-stone)]/60',
  },
}

const ALL_STATUSES: ProjectStatus[] = [
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
  'on_hold',
  'cancelled',
  'archived',
]

// ─── Props ────────────────────────────────────────────────────────────────────

interface ProjectStatusPillProps {
  status: ProjectStatus
  projectId: string
  canEdit: boolean
  onRefresh: () => void
}

// ─── Component ────────────────────────────────────────────────────────────────

export function ProjectStatusPill({
  status,
  projectId,
  canEdit,
  onRefresh,
}: ProjectStatusPillProps) {
  const [open, setOpen] = useState(false)
  const [pendingStatus, setPendingStatus] = useState<ProjectStatus | null>(null)
  const [optimisticStatus, setOptimisticStatus] = useState<ProjectStatus>(status)
  const [isPending, startTransition] = useTransition()

  const cfg = STATUS_CONFIGS[optimisticStatus] ?? STATUS_CONFIGS.planning

  const handleSelect = (next: ProjectStatus) => {
    if (next === optimisticStatus) { setOpen(false); return }
    setPendingStatus(next)
    setOpen(false)
  }

  const confirmChange = () => {
    if (!pendingStatus) return
    const prev = optimisticStatus
    const next = pendingStatus
    setOptimisticStatus(next)
    setPendingStatus(null)

    startTransition(async () => {
      const result = await updateProjectStatusAction(projectId, next)
      if (!result.ok) {
        toast.error(result.error)
        setOptimisticStatus(prev)
      } else {
        toast.success(`Status updated to ${STATUS_CONFIGS[next]?.label ?? next}`)
        onRefresh()
      }
    })
  }

  const pill = (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium transition-opacity',
        cfg.pillClass,
        canEdit && !isPending && 'cursor-pointer hover:opacity-80',
        isPending && 'opacity-60 cursor-wait',
      )}
      aria-label={`Project status: ${cfg.label}`}
    >
      <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', cfg.dotClass)} />
      {cfg.label}
    </span>
  )

  if (!canEdit) return pill

  return (
    <>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild disabled={isPending}>
          {pill}
        </PopoverTrigger>
        <PopoverContent align="start" className="w-44 p-1">
          {ALL_STATUSES.map((s) => {
            const c = STATUS_CONFIGS[s] ?? STATUS_CONFIGS.planning
            return (
              <button
                key={s}
                onClick={() => handleSelect(s)}
                className={cn(
                  'w-full flex items-center gap-2 px-2 py-1.5 rounded text-sm text-left',
                  'hover:bg-[var(--color-stone)]/8 transition-colors',
                  s === optimisticStatus && 'font-medium',
                )}
              >
                <span className={cn('w-2 h-2 rounded-full shrink-0', c.dotClass)} />
                <span className="flex-1">{c.label}</span>
                {s === optimisticStatus && (
                  <Check className="h-3 w-3 text-[var(--color-stone)] shrink-0" />
                )}
              </button>
            )
          })}
        </PopoverContent>
      </Popover>

      {/* Confirm dialog */}
      <AlertDialog open={pendingStatus !== null} onOpenChange={(o) => !o && setPendingStatus(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Change project status?</AlertDialogTitle>
            <AlertDialogDescription>
              {pendingStatus && (
                <>
                  Move from{' '}
                  <strong>{STATUS_CONFIGS[optimisticStatus]?.label ?? optimisticStatus}</strong> to{' '}
                  <strong>{STATUS_CONFIGS[pendingStatus]?.label ?? pendingStatus}</strong>?
                </>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPendingStatus(null)}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmChange}>Confirm</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { ExternalLink, Trash2, ImageIcon, Link2 } from 'lucide-react'
import Masonry from 'react-masonry-css'
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from '@dnd-kit/core'
import {
  SortableContext,
  rectSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { FileDropzone } from '@/components/ui/file-dropzone'
import { cn } from '@/lib/utils'
import {
  addReferenceAction,
  removeReferenceAction,
  reorderReferencesAction,
} from '@/app/(app)/projects/actions'
import type { ProjectWithSessions, ProjectReference } from '@/lib/projects/queries'

// ─── Storage URL helper ────────────────────────────────────────────────────────

function getPublicUrl(storagePath: string): string {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${base}/storage/v1/object/public/project-references/${storagePath}`
}

// ─── Source icons ──────────────────────────────────────────────────────────────

const SOURCE_LABEL: Record<string, string> = {
  pinterest: 'Pinterest',
  instagram: 'Instagram',
  behance: 'Behance',
  url: 'URL',
  upload: 'Upload',
  flash_design: 'Flash',
}

// ─── Sortable reference card ───────────────────────────────────────────────────

interface SortableCardProps {
  reference: ProjectReference
  canWrite: boolean
  onRemove: (id: string) => void
}

function SortableCard({ reference, canWrite, onRemove }: SortableCardProps) {
  const [imgError, setImgError] = useState(false)
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: reference.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  }

  const isUpload = reference.source === 'upload'
  const isExternal = !isUpload && reference.source !== 'flash_design'
  const thumbUrl = isUpload
    ? getPublicUrl(reference.storage_path)
    : (reference.thumbnail_url ?? null)

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className={cn(
        'group relative rounded-lg overflow-hidden border border-[var(--color-border)] shadow-[var(--shadow-soft)]',
        'bg-[var(--color-bone)] mb-4 cursor-grab active:cursor-grabbing',
      )}
    >
      {/* Image */}
      {thumbUrl && !imgError ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={thumbUrl}
          alt={reference.caption ?? 'Reference'}
          className="w-full object-cover"
          onError={() => setImgError(true)}
          draggable={false}
        />
      ) : (
        <div className="flex items-center justify-center h-32 bg-[var(--color-stone)]/5">
          {reference.source === 'flash_design' ? (
            <div className="text-center px-3">
              <span className="inline-block px-2 py-0.5 rounded text-[10px] font-medium bg-[var(--color-stone)]/10 text-[var(--color-stone)] mb-1">
                Flash design
              </span>
            </div>
          ) : (
            <ImageIcon className="h-8 w-8 text-[var(--color-stone)]/30" />
          )}
        </div>
      )}

      {/* Source badge */}
      {reference.source !== 'upload' && (
        <div className="absolute top-1.5 left-1.5">
          <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-[var(--color-onyx)]/70 text-[var(--color-bone)]">
            {SOURCE_LABEL[reference.source] ?? reference.source}
          </span>
        </div>
      )}

      {/* Caption */}
      {reference.caption && (
        <div className="px-2 py-1.5 border-t border-[var(--color-border)]">
          <p className="text-xs text-[var(--color-stone)] line-clamp-2">{reference.caption}</p>
        </div>
      )}

      {/* Hover controls */}
      <div className="absolute top-1.5 right-1.5 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        {isExternal && reference.external_url && (
          <a
            href={reference.external_url}
            target="_blank"
            rel="noopener noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="p-1 rounded bg-[var(--color-onyx)]/50 text-[var(--color-bone)] hover:bg-[var(--color-onyx)]/80 transition-colors"
            aria-label="Open source"
          >
            <ExternalLink className="h-3 w-3" />
          </a>
        )}
        {canWrite && (
          <button
            onClick={(e) => { e.stopPropagation(); onRemove(reference.id) }}
            className="p-1 rounded bg-[var(--color-onyx)]/50 text-[var(--color-bone)] hover:bg-[var(--color-destructive)] transition-colors"
            aria-label="Remove reference"
          >
            <Trash2 className="h-3 w-3" />
          </button>
        )}
      </div>
    </div>
  )
}

// ─── URL paste input ───────────────────────────────────────────────────────────

function PasteUrlInput({
  projectId,
  refCount,
  onRefresh,
}: {
  projectId: string
  refCount: number
  onRefresh: () => void
}) {
  const [url, setUrl] = useState('')
  const [isPending, startTransition] = useTransition()

  const handleAdd = () => {
    const trimmed = url.trim()
    if (!trimmed) return
    startTransition(async () => {
      const fd = new FormData()
      fd.set('url', trimmed)
      fd.set('displayOrder', String(refCount))
      // We call addReferenceAction with url-source branch
      // Since addReferenceAction only handles file uploads, we use the url variant below
      const result = await addUrlReferenceAction(projectId, trimmed, refCount)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      setUrl('')
      toast.success('Reference added')
      onRefresh()
    })
  }

  return (
    <div className="flex gap-2">
      <Input
        value={url}
        onChange={(e) => setUrl(e.target.value)}
        placeholder="Paste Pinterest, Instagram, or Behance URL…"
        className="flex-1 text-sm h-9"
        onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleAdd() } }}
      />
      <Button
