// ─── Props ────────────────────────────────────────────────────────────────────

interface MoodboardTabProps {
  project: ProjectWithSessions
  references: ProjectReference[]
  role: string
  onRefresh: () => void
}

// ─── Masonry breakpoints ───────────────────────────────────────────────────────

const MASONRY_BREAKPOINTS = {
  default: 4,
  1280: 3,
  900: 2,
  640: 2,
}

// ─── Tab ──────────────────────────────────────────────────────────────────────

export function MoodboardTab({
  project,
  references,
  role,
  onRefresh,
}: MoodboardTabProps) {
  const [isPending, startTransition] = useTransition()
  const [uploading, setUploading] = useState(false)
  const [urlValue, setUrlValue] = useState('')
  const [isAddingUrl, setIsAddingUrl] = useState(false)
  const [removingId, setRemovingId] = useState<string | null>(null)
  const [localOrder, setLocalOrder] = useState<string[]>(
    references.map((r) => r.id)
  )

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } })
  )

  const orderedRefs = localOrder
    .map((id) => references.find((r) => r.id === id))
    .filter((r): r is ProjectReference => Boolean(r))

  const handleUpload = (files: File[]) => {
    const file = files[0]
    if (!file) return
    setUploading(true)
    startTransition(async () => {
      const fd = new FormData()
      fd.append('file', file)
      fd.set('displayOrder', String(references.length))
      const result = await addReferenceAction(project.id, fd)
      setUploading(false)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Reference added')
      onRefresh()
    })
  }

  const handleAddUrl = () => {
    const trimmed = urlValue.trim()
    if (!trimmed) return
    setIsAddingUrl(true)
    startTransition(async () => {
      const result = await addUrlRefAction(project.id, trimmed, references.length)
      setIsAddingUrl(false)
      if (!result.ok) { toast.error(result.error); return }
      setUrlValue('')
      toast.success('Reference added')
      onRefresh()
    })
  }

  const handleRemove = (refId: string) => {
    startTransition(async () => {
      const result = await removeReferenceAction(project.id, refId)
      if (!result.ok) { toast.error(result.error); return }
      setLocalOrder((prev) => prev.filter((id) => id !== refId))
      toast.success('Reference removed')
      onRefresh()
    })
    setRemovingId(null)
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    if (!over || active.id === over.id) return

    const oldIdx = localOrder.indexOf(String(active.id))
    const newIdx = localOrder.indexOf(String(over.id))
    if (oldIdx === -1 || newIdx === -1) return

    const newOrder = [...localOrder]
    const [moved] = newOrder.splice(oldIdx, 1)
    if (moved) newOrder.splice(newIdx, 0, moved)
    setLocalOrder(newOrder)

    startTransition(async () => {
      const result = await reorderReferencesAction(project.id, newOrder)
      if (!result.ok) {
        toast.error(result.error)
        setLocalOrder(localOrder)
      }
    })
  }

  return (
    <div className="space-y-4">
      {/* Top bar: 3 inputs */}
      {canWrite && (
        <div className="space-y-3 pb-3 border-b border-[var(--color-border)]">
          {/* 1. Upload */}
          <div>
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-1.5">
              Upload images
            </p>
            <FileDropzone
              accept={{ 'image/*': ['.jpg', '.jpeg', '.png', '.webp', '.gif'] }}
              maxSize={10 * 1024 * 1024}
              maxFiles={1}
              onFilesAccepted={handleUpload}
              loading={uploading}
              disabled={isPending || uploading}
              className="h-14"
            />
          </div>

          {/* 2. Paste URL */}
          <div>
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-1.5">
              Paste URL
            </p>
            <div className="flex gap-2">
              <Input
                value={urlValue}
                onChange={(e) => setUrlValue(e.target.value)}
                placeholder="Pinterest, Instagram, or Behance link…"
                className="flex-1 text-sm h-9"
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleAddUrl() } }}
              />
              <Button
                size="sm"
                onClick={handleAddUrl}
                disabled={isAddingUrl || !urlValue.trim()}
                className="h-9 gap-1.5 shrink-0"
              >
                <Link2 className="h-3.5 w-3.5" />
                Add
              </Button>
            </div>
          </div>

          {/* 3. Flash designs — deferred */}
          <div>
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-1.5">
              Flash designs
            </p>
            <div className="flex items-center gap-2 px-3 py-2 rounded-lg border border-dashed border-[var(--color-border)] text-xs text-[var(--color-stone)]">
              Flash design linking — coming in Sprint 7.
            </div>
          </div>
        </div>
      )}

      {/* Masonry grid */}
      {orderedRefs.length === 0 ? (
        <EmptyMoodboard canWrite={canWrite} />
      ) : (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext items={localOrder} strategy={rectSortingStrategy}>
            <Masonry
              breakpointCols={MASONRY_BREAKPOINTS}
              className="flex w-auto -ml-4"
              columnClassName="pl-4 bg-clip-padding"
            >
              {orderedRefs.map((ref) => (
                <SortableCard
                  key={ref.id}
                  reference={ref}
                  canWrite={canWrite}
                  onRemove={(id) => setRemovingId(id)}
                />
              ))}
            </Masonry>
          </SortableContext>
        </DndContext>
      )}

      {/* Remove confirmation */}
      <AlertDialog
        open={removingId !== null}
        onOpenChange={(open) => !open && setRemovingId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this reference?</AlertDialogTitle>
            <AlertDialogDescription>
              The image will be removed from the moodboard. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => removingId && handleRemove(removingId)}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function EmptyMoodboard({ canWrite }: { canWrite: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center rounded-lg border border-dashed border-[var(--color-border)]">
      <ImageIcon className="h-10 w-10 text-[var(--color-stone)]/40 mb-3" />
      <h3 className="font-serif italic text-[var(--color-onyx)] text-lg mb-1">
        The moodboard.
      </h3>
      <p className="text-xs text-[var(--color-stone)] max-w-[220px]">
        {canWrite
          ? 'Upload reference images or paste links to build the vision.'
          : 'No references added yet.'}
      </p>
    </div>
  )
}

// ─── Server action for URL references ─────────────────────────────────────────
// Kept here as a 'use server' function co-located with the tab since it's tiny.
// This avoids importing server modules in the client component above.

async function addUrlRefAction(
  projectId: string,
  url: string,
  displayOrder: number,
): Promise<{ ok: true } | { ok: false; error: string }> {
  'use server'

  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role
  if (role !== 'owner' && role !== 'admin' && role !== 'artist') {
    return { ok: false, error: 'Insufficient permissions' }
  }

  let source: 'pinterest' | 'instagram' | 'behance' | 'url' = 'url'
  try {
    const { hostname } = new URL(url)
    if (hostname.includes('pinterest.')) source = 'pinterest'
    else if (hostname.includes('instagram.')) source = 'instagram'
    else if (hostname.includes('behance.')) source = 'behance'
  } catch {
    // malformed URL
  }

  const supabase = await createClient()

  const { error } = await supabase
    .from('project_references' as 'projects')
    .insert({
      project_id: projectId,
      storage_path: '',
      source,
      external_url: url,
      thumbnail_url: null,
      display_order: displayOrder,
      created_by: auth.user.id,
    } as never)

  if (error) {
    logger.error({ error, projectId }, 'addUrlRefAction insert failed')
    return { ok: false, error: 'Failed to add reference' }
  }

  revalidatePath(`/projects/${projectId}`)
  return { ok: true }
}

'use server'

import { revalidatePath } from 'next/cache'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

type WriteRole = 'owner' | 'admin' | 'artist'

function isWriteRole(role: string): role is WriteRole {
  return role === 'owner' || role === 'admin' || role === 'artist'
}

function detectSource(url: string): 'pinterest' | 'instagram' | 'behance' | 'url' {
  try {
    const { hostname } = new URL(url)
    if (hostname.includes('pinterest.')) return 'pinterest'
    if (hostname.includes('instagram.')) return 'instagram'
    if (hostname.includes('behance.')) return 'behance'
  } catch {
    // malformed URL
  }
  return 'url'
}

export async function addUrlReferenceAction(
  projectId: string,
  url: string,
  displayOrder: number,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!isWriteRole(auth.role)) return { ok: false, error: 'Insufficient permissions' }

  if (!url.trim()) return { ok: false, error: 'URL cannot be empty' }

  const source = detectSource(url)
  const supabase = await createClient()

  const { error } = await supabase
    .from('project_references' as 'projects')
    .insert({
      project_id: projectId,
      storage_path: '',
      source,
      external_url: url,
      thumbnail_url: null,
      display_order: displayOrder,
      created_by: auth.user.id,
    } as never)

  if (error) {
    logger.error({ error, projectId }, 'addUrlReferenceAction insert failed')
    return { ok: false, error: 'Failed to add reference' }
  }

  revalidatePath(`/projects/${projectId}`)
  return { ok: true }
}

