interface SortableCardProps {
  reference: ProjectReference
  canWrite: boolean
  onRemove: (id: string) => void
}

function SortableCard({ reference, canWrite, onRemove }: SortableCardProps) {
  const [imgError, setImgError] = useState(false)
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: reference.id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  }

  const isUpload = reference.source === 'upload'
  const isExternal = !isUpload && reference.source !== 'flash_design'
  const thumbUrl = isUpload
    ? getPublicUrl(reference.storage_path)
    : (reference.thumbnail_url ?? null)

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className={cn(
        'group relative rounded-lg overflow-hidden border border-[var(--color-border)]',
        'shadow-[var(--shadow-soft)] bg-[var(--color-bone)] mb-4',
        'cursor-grab active:cursor-grabbing',
      )}
