      {/* Image / placeholder */}
      {thumbUrl && !imgError ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={thumbUrl}
          alt={reference.caption ?? 'Reference'}
          className="w-full object-cover"
          onError={() => setImgError(true)}
