              Flash design
            </span>
          ) : isExternal && !thumbUrl ? (
            <p className="text-[11px] text-[var(--color-stone)] px-3 text-center">
              Fetching preview…
            </p>
          ) : (
            <ImageIcon className="h-8 w-8 text-[var(--color-stone)]/30" />
          )}
        </div>
      )}

      {/* Source badge */}
      {reference.source !== 'upload' && (
        <div className="absolute top-1.5 left-1.5">
          <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-[var(--color-onyx)]/70 text-[var(--color-bone)]">
