        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this reference?</AlertDialogTitle>
            <AlertDialogDescription>
              The image will be removed from the moodboard. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => removingId && handleRemove(removingId)}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function EmptyMoodboard({ canWrite }: { canWrite: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center rounded-lg border border-dashed border-[var(--color-border)]">
      <ImageIcon className="h-10 w-10 text-[var(--color-stone)]/40 mb-3" />
      <h3 className="font-serif italic text-[var(--color-onyx)] text-xl mb-1">
        The moodboard.
      </h3>
      <p className="text-xs text-[var(--color-stone)] max-w-[220px]">
        {canWrite
          ? 'Upload reference images or paste links to build the vision.'
          : 'No references added yet.'}
      </p>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { ExternalLink, ShieldCheck, ShieldAlert } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import { DepositPoolLedger } from './DepositPoolLedger'
import type { ProjectWithSessions, ProjectDepositTransactionRow } from '@/lib/projects/queries'

// ─── Shared label ──────────────────────────────────────────────────────────────

const SIZE_LABELS: Record<string, string> = {
  small: 'Small',
  medium: 'Medium',
  large: 'Large',
  extra_large: 'XL',
  full_sleeve: 'Full sleeve',
  full_back: 'Full back',
}

const COLOR_MODE_LABELS: Record<string, string> = {
  color: 'Color',
  black_and_grey: 'B&G',
  both: 'Color + B&G',
}

const APPLY_RULE_LABELS: Record<string, string> = {
  last_session: 'Last session',
  split_evenly: 'Split evenly',
  manual: 'Manual',
}

// ─── Client card ──────────────────────────────────────────────────────────────

interface ClientCardProps {
  project: ProjectWithSessions
  clientLtv: number | null
  priorSessionCount: number
}

function ClientCard({ project, clientLtv, priorSessionCount }: ClientCardProps) {
  const client = project.client
  if (!client) return null

  const name = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
  const isVip = priorSessionCount > 5

  // Obfuscate phone if long
  function obfuscatePhone(phone: string | null): string | null {
    if (!phone) return null
    if (phone.length > 10) {
      const prefix = phone.slice(0, 5)
      const suffix = phone.slice(-5)
      return `${prefix}···${suffix}`
    }
    return phone
  }

  const phone = 'phone' in client ? obfuscatePhone((client as { phone?: string | null }).phone ?? null) : null

  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-bone)] p-4 shadow-[var(--shadow-soft)] space-y-3">
      <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
        Client
      </p>
      <div className="flex items-center gap-3">
        {client.avatar_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={client.avatar_url}
            alt={name}
            className="w-9 h-9 rounded-full object-cover shrink-0"
          />
        ) : (
          <div className="w-9 h-9 rounded-full bg-[var(--color-stone)]/10 flex items-center justify-center shrink-0">
            <span className="text-sm font-medium text-[var(--color-stone)]">
              {client.first_name.charAt(0).toUpperCase()}
            </span>
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5 flex-wrap">
            <p className="text-sm font-medium text-[var(--color-onyx)] truncate">{name}</p>
            {isVip && (
              <span className="px-1.5 py-0.5 rounded-full text-[10px] font-medium bg-[var(--color-stone)]/10 text-[var(--color-stone)] shrink-0">
                VIP
              </span>
            )}
          </div>
          <p className="text-[11px] text-[var(--color-stone)]">
            {priorSessionCount} prior session{priorSessionCount !== 1 ? 's' : ''}
          </p>
        </div>
      </div>

      {/* Meta rows */}
      <div className="space-y-1">
        {phone && (
          <div className="flex items-center gap-2">
            <span className="text-[11px] text-[var(--color-stone)] w-12 shrink-0">Phone</span>
            <span className="text-xs text-[var(--color-onyx)] tabular-nums">{phone}</span>
          </div>
        )}
        {clientLtv !== null && clientLtv > 0 && (
          <div className="flex items-center gap-2">
            <span className="text-[11px] text-[var(--color-stone)] w-12 shrink-0">LTV</span>
            <span className="text-xs font-medium text-[var(--color-onyx)] tabular-nums">
              {formatCurrency(clientLtv)}
            </span>
          </div>
        )}
      </div>

      <Link
        href={`/clients/${client.id}`}
        className="flex items-center gap-1 text-xs text-[var(--color-stone)] hover:text-[var(--color-onyx)] transition-colors"
      >
        <ExternalLink className="h-3 w-3" />
        Open profile
      </Link>
    </div>
  )
}

// ─── Specs card ────────────────────────────────────────────────────────────────

function SpecsCard({ project }: { project: ProjectWithSessions }) {
  const rows: { label: string; value: string | null | undefined }[] = [
    { label: 'Size', value: project.size ? (SIZE_LABELS[project.size as string] ?? project.size) : null },
    { label: 'Placement', value: project.placement },
    { label: 'Style', value: project.style?.replace(/_/g, ' ') ?? null },
    { label: 'Color', value: project.color_mode ? (COLOR_MODE_LABELS[project.color_mode] ?? project.color_mode) : null },
    { label: 'Artist', value: project.primary_artist?.display_name ?? null },
    {
      label: 'Apply rule',
      value: project.deposit_apply_rule
        ? (APPLY_RULE_LABELS[project.deposit_apply_rule] ?? project.deposit_apply_rule)
        : null,
    },
  ]

  const filledRows = rows.filter((r) => r.value)

  if (filledRows.length === 0) return null

  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-bone)] p-4 shadow-[var(--shadow-soft)] space-y-2">
      <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-3">
        Project specs
      </p>
      {filledRows.map(({ label, value }) => (
        <div key={label} className="flex items-baseline gap-2">
          <span className="text-[11px] text-[var(--color-stone)] w-16 shrink-0">{label}</span>
          <span className="text-xs text-[var(--color-onyx)] capitalize">{value}</span>
        </div>
      ))}
    </div>
  )
}

// ─── Related links card ────────────────────────────────────────────────────────

interface RelatedLinksCardProps {
  project: ProjectWithSessions
  messagesCount: number
  paymentsCount: number
  consentSignedAt: string | null
}

function RelatedLinksCard({
  project,
  messagesCount,
  paymentsCount,
  consentSignedAt,
}: RelatedLinksCardProps) {
  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-bone)] p-4 shadow-[var(--shadow-soft)] space-y-2">
      <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)] mb-3">
        Related
      </p>

      <Link
        href={`/inbox?client_id=${project.client_id}`}
        className={cn(
          'flex items-center justify-between py-1 text-sm transition-colors',
          'text-[var(--color-stone)] hover:text-[var(--color-onyx)]',
        )}
      >
        <span>Messages</span>
        <span className="flex items-center gap-1 text-xs tabular-nums">
          {messagesCount}
          <ExternalLink className="h-3 w-3" />
        </span>
      </Link>

      <Link
        href={`/payments?project_id=${project.id}`}
        className={cn(
          'flex items-center justify-between py-1 text-sm transition-colors',
          'text-[var(--color-stone)] hover:text-[var(--color-onyx)]',
        )}
      >
        <span>Payments</span>
        <span className="flex items-center gap-1 text-xs tabular-nums">
          {paymentsCount}
          <ExternalLink className="h-3 w-3" />
        </span>
      </Link>

      <div className="flex items-center gap-2 py-1">
        {consentSignedAt ? (
          <>
            <ShieldCheck className="h-3.5 w-3.5 text-emerald-600 shrink-0" />
            <span className="text-xs text-[var(--color-stone)]">Consent signed</span>
          </>
        ) : (
          <>
            <ShieldAlert className="h-3.5 w-3.5 text-[var(--color-rust)] shrink-0" />
            <span className="text-xs text-[var(--color-stone)]">Consent unsigned</span>
          </>
        )}
      </div>
    </div>
  )
}

// ─── Props ────────────────────────────────────────────────────────────────────

export interface ProjectDetailSidebarProps {
  project: ProjectWithSessions
  transactions: ProjectDepositTransactionRow[]
  canAdmin: boolean
  clientLtv: number | null
  priorSessionCount: number
  messagesCount: number
  paymentsCount: number
  consentSignedAt: string | null
  onRefresh: () => void
}

// ─── Sidebar ──────────────────────────────────────────────────────────────────

export function ProjectDetailSidebar({
  project,
  transactions,
  canAdmin,
  clientLtv,
  priorSessionCount,
  messagesCount,
  paymentsCount,
  consentSignedAt,
  onRefresh,
}: ProjectDetailSidebarProps) {
  return (
    <aside className="hidden lg:flex flex-col gap-4 w-72 shrink-0 self-start sticky top-20">
      {/* Card 1 — Deposit pool ledger */}
      <DepositPoolLedger
        project={project}
        transactions={transactions}
        canAdmin={canAdmin}
        onRefresh={onRefresh}
      />

      {/* Card 2 — Client */}
      <ClientCard
        project={project}
        clientLtv={clientLtv}
        priorSessionCount={priorSessionCount}
      />

      {/* Card 3 — Project specs */}
      <SpecsCard project={project} />

      {/* Card 4 — Related links */}
      <RelatedLinksCard
        project={project}
        messagesCount={messagesCount}
        paymentsCount={paymentsCount}
        consentSignedAt={consentSignedAt}
      />
    </aside>
  )
}

