/**
 * Get client LTV — sum of succeeded payments for a client.
 */
export async function getClientLtv(
  studioId: string,
  clientId: string,
): Promise<number> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('payments')
    .select('amount_cents')
    .eq('studio_id', studioId)
    .eq('client_id', clientId)
    .eq('status', 'succeeded')

  if (error) {
    logger.error({ error, studioId, clientId }, 'getClientLtv failed — returning 0')
    return 0
  }

  return (data ?? []).reduce((sum, p) => sum + p.amount_cents, 0)
}

/**
 * Get count of completed bookings for a client — for prior-session count in sidebar.
 */
export async function getClientSessionCount(
  studioId: string,
  clientId: string,
): Promise<number> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('bookings')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .eq('client_id', clientId)
    .eq('status', 'completed')

  if (error) {
    logger.error({ error, studioId, clientId }, 'getClientSessionCount failed — returning 0')
    return 0
  }

  return count ?? 0
}

/**
 * Get count of conversations for a client in a studio.
 */
export async function getClientConversationsCount(
  studioId: string,
  clientId: string,
): Promise<number> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('conversations')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .eq('client_id', clientId)

  if (error) {
    logger.error({ error, studioId, clientId }, 'getClientConversationsCount failed — returning 0')
    return 0
  }

  return count ?? 0
}

/**
 * Get most recent consent form submission signed_at for a client.
 * Returns null if no consent form submitted.
 */
export async function getClientConsentStatus(
  studioId: string,
  clientId: string,
): Promise<string | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('consent_form_submissions')
    .select('signed_at')
    .eq('studio_id', studioId)
    .eq('client_id', clientId)
    .is('soft_deleted_at', null)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()

  if (error) {
    logger.error({ error, studioId, clientId }, 'getClientConsentStatus failed — returning null')
    return null
  }

  return data?.signed_at ?? null
}

/**
 * Get count of payments linked to a project's bookings.
 */
export async function getProjectPaymentsCount(
  studioId: string,
  projectId: string,
): Promise<number> {
  const supabase = await createClient()

  // Get all booking IDs for this project
  const { data: bookings, error: bookingErr } = await supabase
    .from('bookings')
    .select('id')
    .eq('project_id', projectId)
    .eq('studio_id', studioId)

  if (bookingErr || !bookings || bookings.length === 0) return 0

  const bookingIds = bookings.map((b) => b.id)

  const { count, error } = await supabase
    .from('payments')
    .select('id', { count: 'exact', head: true })
    .in('booking_id', bookingIds)

  if (error) {
    logger.error({ error, studioId, projectId }, 'getProjectPaymentsCount failed — returning 0')
    return 0
  }

  return count ?? 0
}

