import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import {
  getProjectWithSessions,
  getProjectReferences,
  getProjectProgressPhotos,
  getProjectDepositLedger,
  getNextSessionForProject,
  listDepositTransactions,
  listProjectActivity,
  getClientLtv,
  getClientSessionCount,
  getClientConversationsCount,
  getClientConsentStatus,
  getProjectPaymentsCount,
} from '@/lib/projects/queries'
import { ProjectDetailShell } from '@/components/projects/ProjectDetailShell'

interface Props {
  params: Promise<{ id: string }>
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export async function generateMetadata(): Promise<Metadata> {
  return { title: `Project — InkOS` }
}

export default async function ProjectDetailPage({ params, searchParams }: Props) {
  const { id } = await params
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const resolvedParams = await searchParams
  const tab = typeof resolvedParams.tab === 'string' ? resolvedParams.tab : 'sessions'

  // First fetch the project to get client_id for downstream queries
  const project = await getProjectWithSessions(auth.studioId, id)
  if (!project) notFound()

  const clientId = project.client_id

  // 10-way parallel fetch (7 original + 5 new)
  const [
    references,
    progressPhotos,
    depositLedger,
    nextSession,
    depositTransactions,
    activity,
    clientLtv,
    priorSessionCount,
    messagesCount,
    consentSignedAt,
    paymentsCount,
  ] = await Promise.all([
    getProjectReferences(auth.studioId, id),
    getProjectProgressPhotos(auth.studioId, id),
    getProjectDepositLedger(auth.studioId, id).catch(() => null),
    getNextSessionForProject(auth.studioId, id),
    listDepositTransactions(auth.studioId, id),
    listProjectActivity(auth.studioId, id),
    clientId ? getClientLtv(auth.studioId, clientId) : Promise.resolve(null),
    clientId ? getClientSessionCount(auth.studioId, clientId) : Promise.resolve(0),
    clientId ? getClientConversationsCount(auth.studioId, clientId) : Promise.resolve(0),
    clientId ? getClientConsentStatus(auth.studioId, clientId) : Promise.resolve(null),
    getProjectPaymentsCount(auth.studioId, id),
  ])

  return (
    <ProjectDetailShell
      project={project}
      references={references}
      progressPhotos={progressPhotos}
      depositLedger={depositLedger ?? {
        total_pool_cents: project.deposit_pool_cents,
        applied_cents: project.deposit_applied_cents,
        balance_cents: Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents),
        allocations: [],
      }}
      depositTransactions={depositTransactions}
      activity={activity}
      nextSession={nextSession}
      role={auth.role}
      initialTab={tab}
      clientLtv={clientLtv}
      priorSessionCount={priorSessionCount}
      messagesCount={messagesCount}
      consentSignedAt={consentSignedAt}
      paymentsCount={paymentsCount}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn } from '@/lib/utils'
import { archiveProjectAction } from '@/app/(app)/projects/actions'
import { SessionsTab } from './SessionsTab'
import { MoodboardTab } from './MoodboardTab'
import { ProjectHero } from './ProjectHero'
import { PhotoProgressionTimeline } from './PhotoProgressionTimeline'
import { ProjectActivityTab } from './ProjectActivityTab'
import { ProjectDetailSidebar } from './ProjectDetailSidebar'
import type {
  ProjectWithSessions,
  ProjectReference,
  ProjectProgressPhoto,
  ProjectDepositLedger,
  ProjectDepositTransactionRow,
  ProjectActivityLogEntry,
  ProjectSession,
} from '@/lib/projects/queries'

// Re-export so downstream imports resolve cleanly
export type { ProjectDepositTransactionRow, ProjectActivityLogEntry }

// ─── Tabs ─────────────────────────────────────────────────────────────────────

const TABS = [
  { id: 'sessions', label: 'Sessions' },
  { id: 'photos', label: 'Photos' },
  { id: 'moodboard', label: 'Moodboard' },
  { id: 'activity', label: 'Activity' },
] as const

type TabId = (typeof TABS)[number]['id']

// ─── Props ────────────────────────────────────────────────────────────────────

interface ProjectDetailShellProps {
  project: ProjectWithSessions
  references: ProjectReference[]
  progressPhotos: ProjectProgressPhoto[]
  depositLedger: ProjectDepositLedger
  depositTransactions: ProjectDepositTransactionRow[]
  activity: ProjectActivityLogEntry[]
  nextSession: ProjectSession | null
  role: string
  initialTab: string
  // New sidebar props
  clientLtv: number | null
  priorSessionCount: number
  messagesCount: number
  consentSignedAt: string | null
  paymentsCount: number
}

// ─── Shell ────────────────────────────────────────────────────────────────────

export function ProjectDetailShell({
  project,
  references,
  progressPhotos,
  depositTransactions,
  activity,
  nextSession,
  role,
  initialTab,
  clientLtv,
  priorSessionCount,
  messagesCount,
  consentSignedAt,
  paymentsCount,
}: ProjectDetailShellProps) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<TabId>(
    TABS.find((t) => t.id === initialTab)?.id ?? 'sessions'
  )
  const [showArchiveDialog, setShowArchiveDialog] = useState(false)
  const [isPending, startTransition] = useTransition()

  const canAdmin = role === 'owner' || role === 'admin'

  const handleTabChange = (tabId: TabId) => {
    setActiveTab(tabId)
    const url = new URL(window.location.href)
    url.searchParams.set('tab', tabId)
    router.replace(url.pathname + url.search, { scroll: false })
  }

  const handleArchive = () => {
    startTransition(async () => {
      const result = await archiveProjectAction(project.id)
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Project archived')
      router.push('/projects')
    })
    setShowArchiveDialog(false)
  }

  return (
    <div className="flex flex-col min-h-0">
      {/* ── Two-column layout: main + sidebar ── */}
      <div className="flex gap-6 px-4 sm:px-6 pt-6 pb-2 min-h-0">
        {/* Main column */}
        <div className="flex-1 min-w-0 space-y-6">
          {/* Hero */}
          <ProjectHero
            project={project}
            nextSession={nextSession}
            role={role}
            onRefresh={() => router.refresh()}
            onShowArchive={() => setShowArchiveDialog(true)}
          />

          {/* Sticky tab nav */}
          <div className="sticky top-14 z-20 bg-[var(--color-background)] border-b border-[var(--color-border)]/40">
            <nav
              className="flex items-center gap-0 overflow-x-auto scrollbar-none"
              aria-label="Project tabs"
              role="tablist"
            >
              {TABS.map((tab) => {
                const isActive = activeTab === tab.id
                return (
                  <button
                    key={tab.id}
                    role="tab"
                    aria-selected={isActive}
                    onClick={() => handleTabChange(tab.id)}
                    data-active={isActive}
                    className={cn(
                      'relative px-3 py-2.5 text-sm font-medium text-[var(--color-stone)] whitespace-nowrap',
                      'hover:text-[var(--color-onyx)] transition-colors duration-150 ease-out',
                      'after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5',
                      'after:rounded-full after:transition-opacity after:duration-150',
                      isActive
                        ? 'text-[var(--color-onyx)] after:bg-[var(--color-rust)] after:opacity-100'
                        : 'after:opacity-0'
                    )}
                  >
                    {tab.label}
                  </button>
                )
              })}
            </nav>
          </div>

          {/* Tab content */}
          <div className="pb-12" role="tabpanel">
            {activeTab === 'sessions' && (
              <SessionsTab
                project={project}
                role={role}
                onRefresh={() => router.refresh()}
              />
            )}
            {activeTab === 'photos' && (
              <PhotoProgressionTimeline
                project={project}
                photos={progressPhotos}
                role={role}
                onRefresh={() => router.refresh()}
              />
            )}
            {activeTab === 'moodboard' && (
              <MoodboardTab
                project={project}
                references={references}
                role={role}
                onRefresh={() => router.refresh()}
              />
            )}
            {activeTab === 'activity' && (
              <ProjectActivityTab
                projectId={project.id}
                activity={activity}
                onRefresh={() => router.refresh()}
              />
            )}
          </div>
        </div>

        {/* Right sidebar — sticky on desktop, extracted to ProjectDetailSidebar */}
        <ProjectDetailSidebar
          project={project}
          transactions={depositTransactions}
          canAdmin={canAdmin}
          clientLtv={clientLtv}
          priorSessionCount={priorSessionCount}
          messagesCount={messagesCount}
          paymentsCount={paymentsCount}
          consentSignedAt={consentSignedAt}
          onRefresh={() => router.refresh()}
        />
      </div>

      {/* ── Mobile sidebar content (below tabs on small screens) ── */}
      <div className="lg:hidden px-4 sm:px-6 pb-8 space-y-4">
        <ProjectDetailSidebar
          project={project}
          transactions={depositTransactions}
          canAdmin={canAdmin}
          clientLtv={clientLtv}
          priorSessionCount={priorSessionCount}
          messagesCount={messagesCount}
          paymentsCount={paymentsCount}
          consentSignedAt={consentSignedAt}
          onRefresh={() => router.refresh()}
        />
      </div>

      {/* Archive confirmation */}
      <AlertDialog open={showArchiveDialog} onOpenChange={setShowArchiveDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Archive this project?</AlertDialogTitle>
            <AlertDialogDescription>
              Archiving sets the status to cancelled and hides it from the active list.
              All sessions and photos are preserved. You can restore it from Details.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleArchive}
              disabled={isPending}
